module adder_16bit (
    input [15:0] a,
    input [15:0] b,
    input Cin,
    output [15:0] y,
    output Co
);

wire [7:0] sum1, sum2;
wire c1, c2;

assign {c1, sum1} = a[7:0] + b[7:0] + Cin;
assign {c2, sum2} = a[15:8] + b[15:8] + c1;

assign y = {sum2, sum1};

assign Co = c2;
endmodule

