module cla_16bit(
    input [15:0] a,
    input [15:0] b,
    input cin,
    output [15:0] sum,
    output cout,
    output p_group,
    output g_group
);
    wire [3:0] p_4bit; 
    wire [3:0] g_4bit; 
    wire [3:0] c_16bit; 


    cla_4bit cla_block0(
        .a(a[3:0]),
        .b(b[3:0]),
        .cin(cin),
        .sum(sum[3:0]),
        .cout(c_16bit[0]),
        .p_group(p_4bit[0]),
        .g_group(g_4bit[0])
    );


    cla_4bit cla_block1(
        .a(a[7:4]),
        .b(b[7:4]),
        .cin(c_16bit[0]),
        .sum(sum[7:4]),
        .cout(c_16bit[1]),
        .p_group(p_4bit[1]),
        .g_group(g_4bit[1])
    );


    cla_4bit cla_block2(
        .a(a[11:8]),
        .b(b[11:8]),
        .cin(c_16bit[1]),
        .sum(sum[11:8]),
        .cout(c_16bit[2]),
        .p_group(p_4bit[2]),
        .g_group(g_4bit[2])
    );


    cla_4bit cla_block3(
        .a(a[15:12]),
        .b(b[15:12]),
        .cin(c_16bit[2]),
        .sum(sum[15:12]),
        .cout(c_16bit[3]),
        .p_group(p_4bit[3]),
        .g_group(g_4bit[3])
    );


    assign p_group = p_4bit[0] & p_4bit[1] & p_4bit[2] & p_4bit[3];
    assign g_group = g_4bit[3] | 
                    (g_4bit[2] & p_4bit[3]) | 
                    (g_4bit[1] & p_4bit[3] & p_4bit[2]) | 
                    (g_4bit[0] & p_4bit[3] & p_4bit[2] & p_4bit[1]);


    assign cout = c_16bit[3];
endmodule

module cla_4bit(
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout,
    output p_group,
    output g_group
);
    wire [3:0] p; 
    wire [3:0] g; 
    wire [4:0] c; 


    assign p = a ^ b;
    assign g = a & b;


    assign c[0] = cin;
    assign c[1] = g[0] | (p[0] & c[0]);
    assign c[2] = g[1] | (p[1] & c[1]);
    assign c[3] = g[2] | (p[2] & c[2]);
    assign c[4] = g[3] | (p[3] & c[3]);


    assign sum = p ^ {c[3:0]};


    assign p_group = p[0] & p[1] & p[2] & p[3];
    assign g_group = g[3] | (g[2] & p[3]) | (g[1] & p[3] & p[2]) | (g[0] & p[3] & p[2] & p[1]);


    assign cout = c[4];
endmodule

module edge_detect (
    input clk,
    input rst_n,
    input a,
    output reg rise,
    output reg down
);

reg prev_a;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        prev_a <= 1'b0;
    end else begin
        prev_a <= a;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        rise <= 1'b0;
        down <= 1'b0;
    end else begin
        if (prev_a == 1'b0 && a == 1'b1) begin
            rise <= 1'b1;
            down <= 1'b0;
        end else if (prev_a == 1'b1 && a == 1'b0) begin
            rise <= 1'b0;
            down <= 1'b1;
        end else begin
            rise <= 1'b0;
            down <= 1'b0;
        end
    end
end

endmodule

module signal_generator (
    input clk,
    input rst_n,
    output reg [4:0] wave
);

reg [1:0] state;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= 2'b00;
        wave <= 5'b0;
    end else begin
        case(state)
            2'b00: begin
                if (wave == 5'b11111) begin
                    state <= 2'b01;
                end else begin
                    wave <= wave + 1;
                end
            end
            2'b01: begin
                if (wave == 5'b00000) begin
                    state <= 2'b00;
                end else begin
                    wave <= wave - 1;
                end
            end
        endcase
    end
end
endmodule

