module parallel2serial (
    input wire clk,
    input wire rst_n,
    input wire [3:0]d,
    output wire valid_out,
    output wire dout
);

reg [3:0] data;
reg [1:0] cnt;
reg valid;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data <= 4'b0;
        cnt <= 2'b0;
        valid <= 1'b0;
    end else begin
        if (cnt == 2'd3) begin
            data <= d;
            cnt <= 2'b0;
            valid <= 1'b1;
        end else begin
            data <= {data[2:0], data[3]};
            cnt <= cnt + 1'b1;
            valid <= 1'b0;
        end
    end
end

assign dout = data[3];
assign valid_out = valid;

endmodule

module right_shifter (
    input clk,
    output reg [7:0] q,
    input d
);
    initial begin
        q = 8'b0;
    end

    always @(posedge clk) begin
        q <= (q >> 1);
        q[7] <= d;
    end
endmodule

module calendar (
    input CLK,
    input RST,
    output reg [5:0] Hours,
    output reg [5:0] Mins,
    output reg [5:0] Secs
);

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        Secs <= 0;
        Mins <= 0;
        Hours <= 0;
    end else begin
        if (Secs == 59) begin
            Secs <= 0;
            if (Mins == 59) begin
                Mins <= 0;
                if (Hours == 23) begin
                    Hours <= 0;
                end else begin
                    Hours <= Hours + 1;
                end
            end else begin
                Mins <= Mins + 1;
            end
        end else begin
            Secs <= Secs + 1;
        end
    end
end

endmodule

module multi_pipe_4bit #(
    parameter size = 4,
    parameter N = 2 * size
) (
    input 						clk,
    input 						rst_n,
    input	[size-1:0]			mul_a,
    input	[size-1:0]			mul_b,
    output	reg	[size*2-1:0]	mul_out
);

reg [size*2-1:0] sum_tmp1, sum_tmp2;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum_tmp1 <= 0;
        sum_tmp2 <= 0;
    end else begin
        sum_tmp1 <= (mul_b[0] ? mul_a : 0) + (mul_b[1] ? mul_a << 1 : 0);
        sum_tmp2 <= (mul_b[2] ? mul_a << 2 : 0) + (mul_b[3] ? mul_a << 3 : 0);
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_out <= 0;
    end else begin
        mul_out <= sum_tmp1 + sum_tmp2;
    end
end

endmodule

module synchronizer (
    input 				clk_a,
    input 				clk_b,
    input 				arstn,
    input				brstn,
    input		[3:0]	data_in,
    input               data_en,
    output reg  [3:0] 	dataout
);

reg [3:0] data_reg;
always @(posedge clk_a or negedge arstn) begin
    if (~arstn) begin
        data_reg <= 4'd0;
    end else begin
        data_reg <= data_in;
    end
end

reg en_data_reg;
always @(posedge clk_a or negedge arstn) begin
    if (~arstn) begin
        en_data_reg <= 1'd0;
    end else begin
        en_data_reg <= data_en;
    end
end

reg en_clap_one;
reg en_clap_two;
always @(posedge clk_b or negedge brstn) begin
    if (~brstn) begin
        en_clap_one <= 1'd0;
        en_clap_two <= 1'd0;
    end else begin
        en_clap_one <= en_data_reg;
        en_clap_two <= en_clap_one;
    end
end

always @(posedge clk_b or negedge brstn) begin
    if (~brstn) begin
        dataout <= 4'd0;
    end else begin
        if (en_clap_two) begin
            dataout <= data_reg;
        end else begin
            dataout <= dataout;
        end
    end
end
endmodule

module multi_16bit (
    input clk,
    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output [31:0] yout,
    output done
);

reg [31:0] product;
reg done_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        product <= 0;
        done_reg <= 0;
    end else if (start) begin
        product <= ain * bin;
        done_reg <= 1;
    end else begin
        done_reg <= 0;
    end
end

assign yout = product;
assign done = done_reg;

endmodule

module multi_pipe_8bit #(
    parameter size = 8
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    input mul_en_in,
    output reg mul_en_out,
    output reg [size*2-1:0] mul_out
);

reg [3:0] mul_en_out_reg;
reg [7:0] mul_a_reg, mul_b_reg;
reg [15:0] temp[0:7];
reg [15:0] sum[0:3];
reg [15:0] mul_out_reg;
always@(posedge clk or negedge rst_n)begin
	if(!rst_n)begin
		mul_en_out_reg <= 4'd0;
	end
	else begin
		mul_en_out_reg <= {mul_en_out_reg[2:0],mul_en_in};
	end
end
assign mul_en_out = mul_en_out_reg[3];
always@(posedge clk or negedge rst_n)begin
	if(!rst_n)begin
		mul_a_reg <= 8'd0;
		mul_b_reg <= 8'd0;
	end
	else begin
		if(mul_en_in==1'b1)begin
			mul_a_reg <= mul_a;
			mul_b_reg <= mul_b;
		end
		else begin
			mul_a_reg <= 8'd0;
			mul_b_reg <= 8'd0;
		end
	end
end
always@(*)begin
	temp[0] = mul_b_reg[0]?{8'd0,mul_a_reg}:16'd0;
	temp[1] = mul_b_reg[1]?{7'd0,mul_a_reg,1'd0}:16'd0;
	temp[2] = mul_b_reg[2]?{6'd0,mul_a_reg,2'd0}:16'd0;
	temp[3] = mul_b_reg[3]?{5'd0,mul_a_reg,3'd0}:16'd0;
	temp[4] = mul_b_reg[4]?{4'd0,mul_a_reg,4'd0}:16'd0;
	temp[5] = mul_b_reg[5]?{3'd0,mul_a_reg,5'd0}:16'd0;
	temp[6] = mul_b_reg[6]?{2'd0,mul_a_reg,6'd0}:16'd0;
	temp[7] = mul_b_reg[7]?{1'd0,mul_a_reg,7'd0}:16'd0;
end
always@(posedge clk or negedge rst_n)begin
	if(!rst_n)begin
		sum[0] <= 16'd0;
		sum[1] <= 16'd0;
		sum[2] <= 16'd0;
		sum[3] <= 16'd0;
	end
	else begin
		sum[0] <= temp[0]+temp[1];
		sum[1] <= temp[2]+temp[3];
		sum[2] <= temp[4]+temp[5];
		sum[3] <= temp[6]+temp[7];
	end
end
always@(posedge clk or negedge rst_n)begin
	if(!rst_n)begin
		mul_out_reg <= 16'd0;
	end
	else begin
		mul_out_reg <= sum[0]+sum[1]+sum[2]+sum[3];
	end
end
assign mul_out = mul_en_out?mul_out_reg:16'd0;
endmodule

module accu (
    input               clk,
    input               rst_n,
    input       [7:0]   data_in,
    input               valid_in,
    output  reg         valid_out,
    output  reg [9:0]   data_out
);

reg [9:0] accum;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        accum <= 0;
        valid_out <= 0;
    end else begin
        if (valid_in) begin
            accum <= accum + {data_in, 2'b0};
            if (accum[9:4] != 0) begin
                data_out <= accum;
                valid_out <= 1;
            end else begin
                valid_out <= 0;
            end
        end else begin
            valid_out <= 0;
        end
    end
end

endmodule

module freq_div (
    input CLK_in,
    output reg CLK_50,
    output reg CLK_10,
    output reg CLK_1,
    input RST
);

    reg [0:0] cnt_50;
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            cnt_50 <= 1'b0;
        end else begin
            cnt_50 <= ~cnt_50;
        end
    end

    reg [3:0] cnt_10;
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            cnt_10 <= 4'b0;
            CLK_10 <= 1'b0;
        end else if (cnt_10 == 4'd9) begin
            cnt_10 <= 4'b0;
            CLK_10 <= ~CLK_10;
        end else begin
            cnt_10 <= cnt_10 + 1;
        end
    end

    reg [6:0] cnt_100;
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            cnt_100 <= 7'b0;
            CLK_1 <= 1'b0;
        end else if (cnt_100 == 7'd99) begin
            cnt_100 <= 7'b0;
            CLK_1 <= ~CLK_1;
        end else begin
            cnt_100 <= cnt_100 + 1;
        end
    end

    assign CLK_50 = cnt_50;

endmodule

module multi_8bit (
    input [7:0] A,
    input [7:0] B,
    output reg [15:0] product
);

integer i;
reg [15:0] temp_product;

always @(*) begin
    temp_product = 0;

    for (i = 0; i < 8; i = i + 1) begin

        if (B[i])
            temp_product = temp_product + (A << i);
    end
end

assign product = temp_product;
endmodule

module serial2parallel (
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0]dout_parallel,
    output reg dout_valid
);

reg [3:0] cnt;
reg [7:0] temp_dout_parallel;

always @(posedge clk) begin
    if (!rst_n) begin
        cnt <= 4'b0;
        temp_dout_parallel <= 8'b0;
        dout_valid <= 1'b0;
    end else begin
        if (din_valid) begin
            temp_dout_parallel <= {temp_dout_parallel[6:0], din_serial};
            cnt <= cnt + 1'b1;
            if (cnt == 4'b1111) begin
                dout_valid <= 1'b1;
                cnt <= 4'b0;
            end else begin
                dout_valid <= 1'b0;
            end
        end else begin
            dout_valid <= 1'b0;
        end
    end
end

assign dout_parallel = temp_dout_parallel;

endmodule

module traffic_light #(
    parameter idle = 2'd0,
    parameter s1_red = 2'd1,
    parameter s2_yellow = 2'd2,
    parameter s3_green = 2'd3
) (
    input rst_n,
    input clk,
    input pass_request,
    output wire[7:0]clock,
    output reg red,
    output reg yellow,
    output reg green
);


    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;

    always@(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end 
        else begin
            case(state)
                idle: begin
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 0;
                    state <= s1_red;
                end
                s1_red: begin
                    p_red <= 1;
                    p_yellow <= 0;
                    p_green <= 0;
                    if(cnt == 3) begin
                        state <= s3_green;
                    end
                    else begin
                        state <= s1_red;
                    end
                end
                s2_yellow: begin
                    p_red <= 0;
                    p_yellow <= 1;
                    p_green <= 0;
                    if(cnt == 3) begin
                        state <= s1_red;
                    end
                    else begin
                        state <= s2_yellow;
                    end
                end
                s3_green: begin
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 1;
                    if(cnt == 3) begin
                        state <= s2_yellow;
                    end
                    else begin
                        state <= s3_green;
                    end
                end
            endcase
        end
    end

    always@(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            cnt <= 10;
        end
        else begin
            if(pass_request && green && (cnt > 10)) begin
                cnt <= 10;
            end
            else if(!green && p_green) begin
                cnt <= 60;
            end
            else if(!yellow && p_yellow) begin
                cnt <= 5;
            end
            else if(!red && p_red) begin
                cnt <= 10;
            end
            else begin
                cnt <= cnt - 1;
            end
        end
    end

    assign clock = cnt;

    always@(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
        end
        else begin
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end
endmodule

module adder_pipe_64bit #(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
) (
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] adda_reg, addb_reg;
reg [DATA_WIDTH:0] sum;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        adda_reg <= 0;
        addb_reg <= 0;
        sum <= 0;
        o_en <= 0;
    end else begin
        if (i_en) begin
            adda_reg <= adda;
            addb_reg <= addb;
            sum <= {1'b0, adda} + {1'b0, addb};
            o_en <= 1;
        end else begin
            o_en <= 0;
        end
    end
end

assign result = sum;

endmodule

module pulse_detect #(
    parameter s0 = 2'b00,
    parameter s1 = 2'b01,
    parameter s2 = 2'b10,
    parameter s3 = 2'b11
) (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

localparam IDLE = 2'b00;
localparam PULSE_1 = 2'b01;
localparam PULSE_2 = 2'b10;

reg [1:0] state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        data_out <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                if (data_in == 1'b1) begin
                    state <= PULSE_1;
                end else begin
                    data_out <= 1'b0;
                end
            end
            PULSE_1: begin
                if (data_in == 1'b0) begin
                    state <= PULSE_2;
                end else begin
                    state <= IDLE;
                end
            end
            PULSE_2: begin
                if (data_in == 1'b1) begin
                    state <= IDLE;
                    data_out <= 1'b1;
                end else begin
                    state <= PULSE_2;
                end
            end
        endcase
    end
end

endmodule

module alu #(
    parameter ADD = 6'b100000,
    parameter ADDU = 6'b100001,
    parameter SUB = 6'b100010,
    parameter SUBU = 6'b100011,
    parameter AND = 6'b100100,
    parameter OR = 6'b100101,
    parameter XOR = 6'b100110,
    parameter NOR = 6'b100111,
    parameter SLT = 6'b101010,
    parameter SLTU = 6'b101011,
    parameter SLL = 6'b000000,
    parameter SRL = 6'b000010,
    parameter SRA = 6'b000011,
    parameter SLLV = 6'b000100,
    parameter SRLV = 6'b000110,
    parameter SRAV = 6'b000111,
    parameter LUI = 6'b001111
) (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output reg flag
);

    wire [31:0] a_signed, b_signed;
    reg [31:0] res;
    assign a_signed = {{32{a[31]}}, a};
    assign b_signed = {{32{b[31]}}, b};

    always @(*) begin
        case (aluc)
            ADD: begin
                {carry, res} = a_signed + b_signed;
                overflow = carry ^ res[31];
            end
            ADDU: begin
                res = a + b;
                carry = 0;
                overflow = 0;
            end
            SUB: begin
                {carry, res} = a_signed - b_signed;
                overflow = carry ^ res[31];
            end
            SUBU: begin
                res = a - b;
                carry = 0;
                overflow = 0;
            end
            AND: res = a & b;
            OR: res = a | b;
            XOR: res = a ^ b;
            NOR: res = ~(a | b);
            SLT: begin
                res = a_signed < b_signed ? 32'd1 : 32'd0;
                flag = 1'b1;
            end
            SLTU: begin
                res = a < b ? 32'd1 : 32'd0;
                flag = 1'b1;
            end
            SLL: res = a << b[5:0];
            SRL: res = a >> b[5:0];
            SRA: res = $signed(a) >>> b[5:0];
            SLLV: res = a << b[5:0];
            SRLV: res = a >> b[5:0];
            SRAV: res = $signed(a) >>> b[5:0];
            LUI: res = {b, 16'b0};
            default: res = 32'b0;
        endcase
    end

    assign r = res[31:0];
    assign zero = &res == 32'b0;
    assign negative = res[31];

endmodule
